cat <<'EOF' > tests/test_app.py
import pytest
from nenios.app import create_app


@pytest.fixture()
def client():
    app = create_app()
    app.config["TESTING"] = True
    return app.test_client()


def test_dashboard(client):
    resp = client.get("/")
    assert resp.status_code == 200
    assert b"Nenios Child Care Management" in resp.data


def test_classroom_capacity_and_reports(client):
    data = client.get("/api/classrooms").get_json()
    assert any(c["available_spots"] == 1 for c in data)
    billing = client.get("/api/reports/billing").get_json()
    assert billing and billing[0]["outstanding"] == 150.0


def test_health_report(client):
    report = client.get("/api/reports/health").get_json()
    assert any(item["id"] == "ch2" for item in report)


def test_enroll_waiting_child_requires_capacity(client):
    resp = client.post("/api/enroll/ch2", headers={"X-Role": "office", "X-User": "amy"})
    assert resp.status_code == 200
    child = resp.get_json()
    assert child["status"] == "active"
    audit = client.get("/api/audit?q=enroll").get_json()
    assert audit


def test_role_protection(client):
    resp = client.post("/api/families", json={"id": "f2", "name": "Jones", "contacts": []})
    assert resp.status_code == 403
EOF

