from dataclasses import dataclass, field, asdict
from datetime import date, datetime
from typing import Dict, List, Optional
from flask import Flask, jsonify, request, abort, render_template


@dataclass
class AuditEntry:
    timestamp: str
    actor: str
    action: str
    entity: str
    entity_id: str
    details: str


@dataclass
class Child:
    id: str
    name: str
    age_group: str
    status: str = "waiting"
    family_id: str = ""
    health_info: str = ""
    immunizations_current: bool = False
    waiting_list_position: Optional[int] = None
    classroom_id: Optional[str] = None


@dataclass
class Family:
    id: str
    name: str
    contacts: List[str]
    children: List[str] = field(default_factory=list)


@dataclass
class Classroom:
    id: str
    name: str
    age_group: str
    capacity: int
    enrolled_children: List[str] = field(default_factory=list)

    @property
    def available_spots(self) -> int:
        return max(self.capacity - len(self.enrolled_children), 0)


@dataclass
class Invoice:
    id: str
    family_id: str
    child_id: str
    amount: float
    description: str
    paid: float = 0.0

    @property
    def outstanding(self) -> float:
        return round(max(self.amount - self.paid, 0.0), 2)


class DataStore:
    def __init__(self):
        self.families: Dict[str, Family] = {}
        self.children: Dict[str, Child] = {}
        self.classrooms: Dict[str, Classroom] = {}
        self.invoices: Dict[str, Invoice] = {}
        self.audit: List[AuditEntry] = []

    def log(self, actor: str, action: str, entity: str, entity_id: str, details: str):
        self.audit.append(AuditEntry(datetime.utcnow().isoformat() + "Z", actor, action, entity, entity_id, details))


def seed(store: DataStore):
    store.classrooms["c1"] = Classroom("c1", "Tadpoles", "infant", 2)
    store.classrooms["c2"] = Classroom("c2", "Frogs", "toddler", 1)
    store.families["f1"] = Family("f1", "Smith", ["smith@example.com"])
    store.children["ch1"] = Child("ch1", "Alice Smith", "infant", "active", "f1", "Healthy", True, None, "c1")
    store.children["ch2"] = Child("ch2", "Bob Smith", "infant", "waiting", "f1", "Needs physical", False, 1, None)
    store.families["f1"].children = ["ch1", "ch2"]
    store.classrooms["c1"].enrolled_children = ["ch1"]
    store.invoices["i1"] = Invoice("i1", "f1", "ch1", 250.0, "Weekly tuition", 100.0)
    store.log("system", "seed", "system", "seed", "Seeded initial records")


def require_role(role: str):
    actor_role = request.headers.get("X-Role", "guest")
    allowed = {
        "admin": {"admin", "office"},
        "office": {"office"},
        "teacher": {"teacher"},
        "parent": {"parent"},
    }
    if role not in allowed.get(actor_role, set()):
        abort(403)


def create_app():
    app = Flask(__name__)
    app.store = DataStore()
    seed(app.store)

    @app.get("/")
    def index():
        return render_template(
            "dashboard.html",
            families=app.store.families.values(),
            children=app.store.children.values(),
            classrooms=app.store.classrooms.values(),
            invoices=app.store.invoices.values(),
            audit=app.store.audit[-10:],
        )

    @app.get("/api/dashboard")
    def dashboard():
        return jsonify({
            "daily_snapshot": {
                "enrolled_children": sum(1 for c in app.store.children.values() if c.status == "active"),
                "classroom_occupancy": {cid: {"name": c.name, "age_group": c.age_group, "available_spots": c.available_spots, "enrolled": len(c.enrolled_children)} for cid, c in app.store.classrooms.items()},
            },
            "waiting_list": [{"id": c.id, "name": c.name, "age_group": c.age_group, "position": c.waiting_list_position} for c in sorted(app.store.children.values(), key=lambda x: (x.waiting_list_position or 9999, x.name)) if c.status == "waiting"],
            "billing_summary": [{"id": i.id, "family_id": i.family_id, "child_id": i.child_id, "amount": i.amount, "paid": i.paid, "outstanding": i.outstanding} for i in app.store.invoices.values()],
            "health_reminders": [{"id": c.id, "name": c.name, "immunizations_current": c.immunizations_current, "health_info": c.health_info} for c in app.store.children.values() if not c.immunizations_current or not c.health_info],
        })

    @app.post("/api/families")
    def create_family():
        require_role("office")
        payload = request.get_json(force=True)
        family = Family(payload["id"], payload["name"], payload.get("contacts", []), payload.get("children", []))
        app.store.families[family.id] = family
        app.store.log(request.headers.get("X-User", "unknown"), "create", "family", family.id, family.name)
        return jsonify(asdict(family)), 201

    @app.post("/api/children")
    def create_child():
        require_role("office")
        payload = request.get_json(force=True)
        child = Child(**payload)
        app.store.children[child.id] = child
        app.store.families[child.family_id].children.append(child.id)
        app.store.log(request.headers.get("X-User", "unknown"), "create", "child", child.id, child.name)
        return jsonify(asdict(child)), 201

    @app.post("/api/enroll/<child_id>")
    def enroll_child(child_id):
        require_role("office")
        child = app.store.children[child_id]
        classroom = next((c for c in app.store.classrooms.values() if c.age_group == child.age_group and c.available_spots > 0), None)
        if not classroom:
            abort(409, description="No available spot for matching age group")
        classroom.enrolled_children.append(child.id)
        child.status = "active"
        child.classroom_id = classroom.id
        child.waiting_list_position = None
        app.store.log(request.headers.get("X-User", "unknown"), "enroll", "child", child.id, f"Moved to {classroom.id}")
        return jsonify(asdict(child))

    @app.get("/api/waiting-list/next")
    def next_in_line():
        age_group = request.args.get("age_group")
        candidates = [c for c in app.store.children.values() if c.status == "waiting" and c.age_group == age_group]
        candidate = sorted(candidates, key=lambda c: (c.waiting_list_position or 9999, c.name))[:1]
        return jsonify(asdict(candidate[0]) if candidate else {})

    @app.get("/api/classrooms")
    def classrooms():
        return jsonify([{"id": c.id, "name": c.name, "age_group": c.age_group, "capacity": c.capacity, "enrolled": len(c.enrolled_children), "available_spots": c.available_spots} for c in app.store.classrooms.values()])

    @app.patch("/api/children/<child_id>/health")
    def update_health(child_id):
        require_role("office")
        payload = request.get_json(force=True)
        child = app.store.children[child_id]
        child.health_info = payload.get("health_info", child.health_info)
        child.immunizations_current = payload.get("immunizations_current", child.immunizations_current)
        app.store.log(request.headers.get("X-User", "unknown"), "update", "child", child.id, "Updated health/immunization")
        return jsonify(asdict(child))

    @app.post("/api/invoices")
    def create_invoice():
        require_role("office")
        payload = request.get_json(force=True)
        invoice = Invoice(**payload)
        app.store.invoices[invoice.id] = invoice
        app.store.log(request.headers.get("X-User", "unknown"), "create", "invoice", invoice.id, f"{invoice.amount}")
        return jsonify({**asdict(invoice), "outstanding": invoice.outstanding}), 201

    @app.get("/api/reports/billing")
    def billing_report():
        return jsonify([{"id": i.id, "family_id": i.family_id, "child_id": i.child_id, "amount": i.amount, "paid": i.paid, "outstanding": i.outstanding} for i in app.store.invoices.values() if i.outstanding > 0])

    @app.get("/api/reports/health")
    def health_report():
        return jsonify([{"id": c.id, "name": c.name, "health_info": c.health_info, "immunizations_current": c.immunizations_current} for c in app.store.children.values() if not c.immunizations_current or not c.health_info])

    @app.get("/api/audit")
    def audit_log():
        q = request.args.get("q", "").lower()
        entries = [asdict(e) for e in app.store.audit if q in (e.actor + e.action + e.entity + e.entity_id + e.details).lower()]
        return jsonify(entries)

    return app


app = create_app()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000, debug=True)
